package com.trainflow.program; import jakarta.persistence.*; import java.math.*; import java.time.Instant; import java.util.*; import java.util.UUID; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes;
@Entity @Table(name="training_program_items") public class TrainingProgramItem{@Id @JdbcTypeCode(SqlTypes.VARCHAR)@Column(columnDefinition="char(36)")private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="training_program_day_id")private TrainingProgramDay day;@JdbcTypeCode(SqlTypes.VARCHAR)@Column(name="parent_id",columnDefinition="char(36)")private UUID parentId;@Enumerated(EnumType.STRING)@Column(name="item_type",nullable=false,length=20)private ProgramItemType itemType;@Column(nullable=false,length=250)private String title;@Column(columnDefinition="text")private String content;@Column(name="theory_minutes",nullable=false)private int theoryMinutes;@Column(name="practice_minutes",nullable=false)private int practiceMinutes;@Column(name="duration_hours",nullable=false,precision=8,scale=2)private BigDecimal durationHours=BigDecimal.ZERO;@Column(name="order_index",nullable=false)private int position;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;@JdbcTypeCode(SqlTypes.JSON)@Column(name="method_type",nullable=false,columnDefinition="json")private Set<PedagogicalMethod> methods=new LinkedHashSet<>();protected TrainingProgramItem(){}public TrainingProgramItem(TrainingProgramDay d,ProgramItemType type,UUID parent,String title,int pos){id=UUID.randomUUID();day=d;itemType=type;parentId=parent;this.title=title;position=pos;}@PrePersist void insert(){var n=Instant.now();if(id==null)id=UUID.randomUUID();if(createdAt==null)createdAt=n;syncDuration();updatedAt=n;}@PreUpdate void update(){syncDuration();updatedAt=Instant.now();}private void syncDuration(){durationHours=BigDecimal.valueOf((long)theoryMinutes+practiceMinutes).divide(BigDecimal.valueOf(60),2,RoundingMode.HALF_UP);}public UUID getId(){return id;}public TrainingProgramDay getDay(){return day;}public UUID getParentId(){return parentId;}public ProgramItemType getItemType(){return itemType;}public String getTitle(){return title;}public void setTitle(String v){title=v;}public String getContent(){return content;}public void setContent(String v){content=v;}public int getTheoryMinutes(){return theoryMinutes;}public void setTheoryMinutes(int v){theoryMinutes=v;syncDuration();}public int getPracticeMinutes(){return practiceMinutes;}public void setPracticeMinutes(int v){practiceMinutes=v;syncDuration();}public BigDecimal getDurationHours(){return durationHours;}public int getPosition(){return position;}public void setPosition(int v){position=v;}public Set<PedagogicalMethod> getMethods(){return methods;}}
